 const p=P.validationProgrammeV152(state,programmeId),node=P.validationNodesV152(state,programmeId).find(x=>x.id===nodeId),duts=P.validationDutsForProgrammeV152(state,programmeId),alloc=(state.dutAllocations||[]).filter(x=>x.programmeId===programmeId),consumed=new Set();for(const r of P.validationResultsForProgrammeV152(state,programmeId))if(r.destructiveConsumed)for(const id of r.dutIds||[])consumed.add(id);const already=new Set(alloc.filter(a=>a.nodeId!==nodeId&&!a.reuseAllowed).flatMap(a=>a.dutIds||[]));const usable=duts.filter(d=>!consumed.has(d.id)&&!['Lost','Damaged','Consumed'].includes(d.status));return {programme:p,node,total:duts.length,usable,availableForExclusive:usable.filter(d=>!already.has(d.id)),consumed:[...consumed]};
